### Process Query with Tool Call Handling in TypeScript

Source: https://github.com/modelcontextprotocol/typescript-sdk/blob/main/docs/client-quickstart.md

Handles incoming queries by sending them to Claude API, processing responses, and executing tool calls through the MCP server. Manages multi-turn conversations by collecting tool results and sending follow-up requests to Claude. Returns aggregated text responses from all processing steps.

```typescript
async processQuery(query: string) {
  const messages: Anthropic.MessageParam[] = [
    {
      role: 'user',
      content: query,
    },
  ];

  // Initial Claude API call
  const response = await this.anthropic.messages.create({
    model: ANTHROPIC_MODEL,
    max_tokens: 1000,
    messages,
    tools: this.tools,
  });

  // Process response and handle tool calls
  const finalText = [];

  for (const content of response.content) {
    if (content.type === 'text') {
      finalText.push(content.text);
    } else if (content.type === 'tool_use') {
      // Execute tool call
      const toolName = content.name;
      const toolArgs = content.input as Record<string, unknown> | undefined;
      const result = await this.mcp.callTool({
        name: toolName,
        arguments: toolArgs,
      });

      finalText.push(`[Calling tool ${toolName} with args ${JSON.stringify(toolArgs)}]`);

      // Extract text from tool result content blocks
      const toolResultText = result.content
        .filter((block) => block.type === 'text')
        .map((block) => block.text)
        .join('\n');

      // Continue conversation with tool results
      messages.push({
        role: 'assistant',
        content: response.content,
      });
      messages.push({
        role: 'user',
        content: [{
          type: 'tool_result',
          tool_use_id: content.id,
          content: toolResultText,
        }],
      });

      // Get next response from Claude
      const followUp = await this.anthropic.messages.create({
        model: ANTHROPIC_MODEL,
        max_tokens: 1000,
        messages,
      });

      finalText.push(followUp.content[0].type === 'text' ? followUp.content[0].text : '');
    }
  }

  return finalText.join('\n');
}
