### Setting up a streamable HTTP server transport in TypeScript

Source: https://context7.com/modelcontextprotocol/typescript-sdk/llms.txt

Implement NodeStreamableHTTPServerTransport with Express for remote server access. This setup includes DNS rebinding protection and session management for multiple clients.

```typescript
import { randomUUID } from 'node:crypto';
import { createMcpExpressApp } from '@modelcontextprotocol/express';
import { NodeStreamableHTTPServerTransport } from '@modelcontextprotocol/node';
import { McpServer, isInitializeRequest } from '@modelcontextprotocol/server';
import cors from 'cors';
import * as z from 'zod/v4';

const server = new McpServer({ name: 'http-server', version: '1.0.0' });
server.registerTool('greet', {
  description: 'Greet a user',
  inputSchema: z.object({ name: z.string() })
}, async ({ name }) => ({
  content: [{ type: 'text', text: `Hello, ${name}!` }]
}));

// Create Express app with DNS rebinding protection
const app = createMcpExpressApp();
app.use(cors({
  exposedHeaders: ['WWW-Authenticate', 'Mcp-Session-Id', 'Mcp-Protocol-Version'],
  origin: '*'
}));

// Store transports by session ID
const transports: Map<string, NodeStreamableHTTPServerTransport> = new Map();

app.post('/mcp', async (req, res) => {
  const sessionId = req.headers['mcp-session-id'] as string | undefined;

  if (sessionId && transports.has(sessionId)) {
    // Reuse existing transport
    await transports.get(sessionId)!.handleRequest(req, res, req.body);
  } else if (!sessionId && isInitializeRequest(req.body)) {
    // New session initialization
    const transport = new NodeStreamableHTTPServerTransport({
      sessionIdGenerator: () => randomUUID(),
      onsessioninitialized: sid => transports.set(sid, transport)
    });
    transport.onclose = () => {
      if (transport.sessionId) transports.delete(transport.sessionId);
    };
    await server.connect(transport);
    await transport.handleRequest(req, res, req.body);
  } else {
    res.status(400).json({ error: 'Invalid request' });
  }
});

app.listen(3000, () => console.log('MCP server listening on port 3000'));
```

