import { describe, expect, it, vi } from "vitest";

import {
	createNodeLikeRequest,
	createServerResponseAdapter,
} from "#/mcp/http-adapter";

describe("mcp http adapter", () => {
	it("adapts a fetch request into the minimal node-like shape used by SSE transport", () => {
		const request = new Request(
			"http://localhost:3000/api/mcp/messages?sessionId=session-1",
			{
				method: "POST",
				headers: {
					"content-type": "application/json",
				},
				body: JSON.stringify({ hello: "world" }),
			},
		);

		const adapted = createNodeLikeRequest(request);

		expect(adapted.url).toBe("/api/mcp/messages?sessionId=session-1");
		expect(adapted.headers["content-type"]).toBe("application/json");
	});

	it("builds a streaming Response from node-style write calls", async () => {
		const onClose = vi.fn();
		const adapter = createServerResponseAdapter(onClose);

		adapter.nodeResponse.writeHead(200, {
			"Content-Type": "text/event-stream",
		});
		adapter.nodeResponse.write("event: message\n");
		adapter.nodeResponse.end("data: hello\n\n");

		const response = adapter.toResponse();

		expect(response.status).toBe(200);
		expect(response.headers.get("content-type")).toBe("text/event-stream");
		expect(await response.text()).toBe("event: message\ndata: hello\n\n");
		expect(onClose).toHaveBeenCalledTimes(1);
	});
});

