type HeaderValue = string | Array<string>;

type NodeResponseLike = {
	end: (chunk?: string | Uint8Array) => NodeResponseLike;
	on: (event: "close", listener: () => void) => NodeResponseLike;
	write: (chunk: string | Uint8Array) => boolean;
	writeHead: (
		status: number,
		headers?: Record<string, HeaderValue>,
	) => NodeResponseLike;
};

export function createNodeLikeRequest(request: Request) {
	const url = new URL(request.url);
	const headers = Object.fromEntries(
		Array.from(request.headers.entries()).map(([key, value]) => [
			key.toLowerCase(),
			value,
		]),
	);

	return {
		headers,
		socket: {},
		url: `${url.pathname}${url.search}`,
	};
}

export function createServerResponseAdapter(onClose?: () => void) {
	const encoder = new TextEncoder();
	const closeListeners = new Set<() => void>();
	const headers = new Headers();

	let status = 200;
	let isClosed = false;
	let controller: ReadableStreamDefaultController<Uint8Array> | undefined;

	const emitClose = () => {
		if (isClosed) {
			return;
		}

		isClosed = true;
		for (const listener of closeListeners) {
			listener();
		}
		onClose?.();
	};

	const stream = new ReadableStream<Uint8Array>({
		cancel() {
			emitClose();
		},
		start(streamController) {
			controller = streamController;
		},
	});

	const nodeResponse: NodeResponseLike = {
		end(chunk) {
			if (chunk !== undefined) {
				nodeResponse.write(chunk);
			}
			controller?.close();
			emitClose();
			return nodeResponse;
		},
		on(event, listener) {
			if (event === "close") {
				closeListeners.add(listener);
			}
			return nodeResponse;
		},
		write(chunk) {
			controller?.enqueue(
				typeof chunk === "string" ? encoder.encode(chunk) : chunk,
			);
			return true;
		},
		writeHead(nextStatus, nextHeaders) {
			status = nextStatus;

			if (nextHeaders) {
				for (const [name, value] of Object.entries(nextHeaders)) {
					headers.set(
						name,
						Array.isArray(value) ? value.join(", ") : value,
					);
				}
			}

			return nodeResponse;
		},
	};

	return {
		nodeResponse,
		toResponse() {
			return new Response(stream, {
				headers,
				status,
			});
		},
	};
}

