import { and, desc, eq, like } from "drizzle-orm";
import { z } from "zod";

import { db } from "#/db/index";
import * as schema from "#/db/schema";

type AppDatabase = typeof db;

const listPropertiesSchema = z.object({
	search: z.string().trim().min(1).optional(),
	limit: z.coerce.number().int().positive().max(100).default(25),
});

const getPropertyHierarchySchema = z.object({
	propertyId: z.string().trim().min(1),
});

const listFactsSchema = z.object({
	propertyId: z.string().trim().min(1).optional(),
	category: z.string().trim().min(1).optional(),
	key: z.string().trim().min(1).optional(),
	sourceId: z.string().trim().min(1).optional(),
	limit: z.coerce.number().int().positive().max(100).default(50),
});

const listCasesSchema = z.object({
	propertyId: z.string().trim().min(1).optional(),
	houseId: z.string().trim().min(1).optional(),
	apartmentId: z.string().trim().min(1).optional(),
	status: z.string().trim().min(1).optional(),
	ownerUserId: z.string().trim().min(1).optional(),
	limit: z.coerce.number().int().positive().max(100).default(50),
});

type ToolDefinition<TSchema extends z.ZodTypeAny> = {
	description: string;
	schema: TSchema;
	execute: (args: z.infer<TSchema>) => Promise<unknown>;
};

export function createToolRegistry(database: AppDatabase = db) {
	return {
		list_properties: {
			description: "Lists properties available in the hierarchy database.",
			schema: listPropertiesSchema,
			execute: async ({ limit, search }) => {
				const searchFilter = search
					? like(schema.properties.name, `%${search}%`)
					: undefined;

				return database.query.properties.findMany({
					where: searchFilter,
					limit,
					orderBy: [schema.properties.name],
				});
			},
		},
		get_property_hierarchy: {
			description:
				"Fetches one property with its houses and apartments in hierarchical form.",
			schema: getPropertyHierarchySchema,
			execute: async ({ propertyId }) => {
				const property = await database.query.properties.findFirst({
					where: eq(schema.properties.id, propertyId),
					with: {
						houses: {
							with: {
								apartments: true,
							},
						},
					},
				});

				if (!property) {
					throw new Error(`Property not found: ${propertyId}`);
				}

				return property;
			},
		},
		list_facts: {
			description:
				"Lists facts with optional filtering by property, category, key, or source.",
			schema: listFactsSchema,
			execute: async ({ category, key, limit, propertyId, sourceId }) => {
				const filters = [
					propertyId ? eq(schema.facts.propertyId, propertyId) : undefined,
					category ? eq(schema.facts.category, category) : undefined,
					key ? eq(schema.facts.key, key) : undefined,
					sourceId ? eq(schema.facts.sourceId, sourceId) : undefined,
				].filter(Boolean);

				return database.query.facts.findMany({
					where: filters.length > 0 ? and(...filters) : undefined,
					limit,
					orderBy: [desc(schema.facts.id)],
					with: {
						property: true,
						source: true,
					},
				});
			},
		},
		list_cases: {
			description:
				"Lists cases with optional filtering by scope, status, or owner.",
			schema: listCasesSchema,
			execute: async ({
				apartmentId,
				houseId,
				limit,
				ownerUserId,
				propertyId,
				status,
			}) => {
				const filters = [
					propertyId ? eq(schema.cases.propertyId, propertyId) : undefined,
					houseId ? eq(schema.cases.houseId, houseId) : undefined,
					apartmentId ? eq(schema.cases.apartmentId, apartmentId) : undefined,
					status ? eq(schema.cases.status, status) : undefined,
					ownerUserId ? eq(schema.cases.ownerUserId, ownerUserId) : undefined,
				].filter(Boolean);

				return database.query.cases.findMany({
					where: filters.length > 0 ? and(...filters) : undefined,
					limit,
					orderBy: [desc(schema.cases.updatedAt)],
					with: {
						apartment: true,
						house: true,
						owner: true,
						property: true,
					},
				});
			},
		},
	} satisfies Record<string, ToolDefinition<z.ZodTypeAny>>;
}

export const tools = createToolRegistry();

export type ToolRegistry = typeof tools;
export type ToolName = keyof ToolRegistry;

export function listToolsForMcp(toolRegistry: ToolRegistry) {
	return Object.entries(toolRegistry).map(([name, tool]) => ({
		name,
		description: tool.description,
		inputSchema: z.toJSONSchema(tool.schema),
	}));
}

export async function executeTool<TName extends ToolName>(
	toolRegistry: ToolRegistry,
	name: TName,
	args: unknown,
) {
	const tool = toolRegistry[name];

	if (!tool) {
		throw new Error(`Tool not found: ${String(name)}`);
	}

	const parsedArgs = tool.schema.parse(args ?? {});
	return tool.execute(parsedArgs);
}

