type HeaderValue = string | Array<string>;

type NodeResponseLike = {
	end: (chunk?: string | Uint8Array) => NodeResponseLike;
	on: (event: "close", listener: () => void) => NodeResponseLike;
	write: (chunk: string | Uint8Array) => boolean;
	writeHead: (
		status: number,
		headers?: Record<string, HeaderValue>,
	) => NodeResponseLike;
};

export function createNodeLikeRequest(request: Request) {
	const url = new URL(request.url);
	const headers = Object.fromEntries(
		Array.from(request.headers.entries()).map(([key, value]) => [
			key.toLowerCase(),
			value,
		]),
	);

	return {
		headers,
		socket: {},
		url: `${url.pathname}${url.search}`,
	};
}

export function createServerResponseAdapter(onClose?: () => void) {
	const encoder = new TextEncoder();
	const closeListeners = new Set<() => void>();
	const headers = new Headers();

	let status = 200;
	let isClosed = false;
	let controller: ReadableStreamDefaultController<Uint8Array> | undefined;

	const emitClose = () => {
		if (isClosed) {
			return;
		}

		isClosed = true;
		for (const listener of closeListeners) {
			listener();
		}
		onClose?.();
	};

	const stream = new ReadableStream<Uint8Array>({
		cancel() {
			emitClose();
		},
		start(streamController) {
			controller = streamController;
		},
	});

	const nodeResponse: NodeResponseLike = {
		end(chunk) {
			if (chunk !== undefined) {
				nodeResponse.write(chunk);
			}
			controller?.close();
			emitClose();
			return nodeResponse;
		},
		on(event, listener) {
			if (event === "close") {
				closeListeners.add(listener);
			}
			return nodeResponse;
		},
		write(chunk) {
			controller?.enqueue(
				typeof chunk === "string" ? encoder.encode(chunk) : chunk,
			);
			return true;
		},
		writeHead(nextStatus, nextHeaders) {
			status = nextStatus;

			if (nextHeaders) {
				for (const [name, value] of Object.entries(nextHeaders)) {
					headers.set(name, Array.isArray(value) ? value.join(", ") : value);
				}
			}

			return nodeResponse;
		},
	};

	return {
		nodeResponse,
		toResponse() {
			return new Response(stream, {
				headers,
				status,
			});
		},
	};
}

import { describe, expect, it, vi } from "vitest";

import {
	createNodeLikeRequest,
	createServerResponseAdapter,
} from "#/mcp/http-adapter";

describe("mcp http adapter", () => {
	it("adapts a fetch request into the minimal node-like shape used by SSE transport", () => {
		const request = new Request(
			"http://localhost:3000/api/mcp/messages?sessionId=session-1",
			{
				method: "POST",
				headers: {
					"content-type": "application/json",
				},
				body: JSON.stringify({ hello: "world" }),
			},
		);

		const adapted = createNodeLikeRequest(request);

		expect(adapted.url).toBe("/api/mcp/messages?sessionId=session-1");
		expect(adapted.headers["content-type"]).toBe("application/json");
	});

	it("builds a streaming Response from node-style write calls", async () => {
		const onClose = vi.fn();
		const adapter = createServerResponseAdapter(onClose);

		adapter.nodeResponse.writeHead(200, {
			"Content-Type": "text/event-stream",
		});
		adapter.nodeResponse.write("event: message\n");
		adapter.nodeResponse.end("data: hello\n\n");

		const response = adapter.toResponse();

		expect(response.status).toBe(200);
		expect(response.headers.get("content-type")).toBe("text/event-stream");
		expect(await response.text()).toBe("event: message\ndata: hello\n\n");
		expect(onClose).toHaveBeenCalledTimes(1);
	});
});

