import { describe, expect, it } from "vitest";

import { handleMcpHttpRequest } from "#/mcp/server";

function createMcpPostRequest(body: unknown, headers?: HeadersInit) {
	return new Request("http://localhost:3000/api/mcp", {
		method: "POST",
		headers: {
			accept: "application/json, text/event-stream",
			"content-type": "application/json",
			...headers,
		},
		body: JSON.stringify(body),
	});
}

describe("mcp http transport", () => {
	it("handles initialize requests over streamable HTTP", async () => {
		const response = await handleMcpHttpRequest(
			createMcpPostRequest({
				jsonrpc: "2.0",
				id: 1,
				method: "initialize",
				params: {
					protocolVersion: "2025-03-26",
					capabilities: {},
					clientInfo: {
						name: "vitest-client",
						version: "1.0.0",
					},
				},
			}),
		);

		expect(response.status).toBe(200);
		expect(response.headers.get("content-type")).toContain(
			"text/event-stream",
		);

		const payload = await response.text();
		expect(payload).toContain('"method":"initialize"');
		expect(payload).toContain('"protocolVersion":"2025-03-26"');
	});

	it("lists tools and calls them through the same /api/mcp endpoint", async () => {
		const toolsResponse = await handleMcpHttpRequest(
			createMcpPostRequest(
				{
					jsonrpc: "2.0",
					id: 2,
					method: "tools/list",
					params: {},
				},
				{
					"mcp-protocol-version": "2025-03-26",
				},
			),
		);

		expect(toolsResponse.status).toBe(200);
		const toolsPayload = await toolsResponse.text();
		expect(toolsPayload).toContain('"name":"list_properties"');
		expect(toolsPayload).toContain('"name":"get_property_hierarchy"');

		const callResponse = await handleMcpHttpRequest(
			createMcpPostRequest(
				{
					jsonrpc: "2.0",
					id: 3,
					method: "tools/call",
					params: {
						name: "list_properties",
						arguments: {
							limit: 1,
						},
					},
				},
				{
					"mcp-protocol-version": "2025-03-26",
				},
			),
		);

		expect(callResponse.status).toBe(200);
		const callPayload = await callResponse.text();
		expect(callPayload).toContain('"method":"tools/call"');
		expect(callPayload).toContain('"content"');
	});

	it("rejects unsupported methods for stateless streamable HTTP", async () => {
		const response = await handleMcpHttpRequest(
			new Request("http://localhost:3000/api/mcp", {
				method: "GET",
			}),
		);

		expect(response.status).toBe(405);
	});
});

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { SSEServerTransport } from "@modelcontextprotocol/sdk/server/sse.js";
import {
	CallToolRequestSchema,
	ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";

import {
	createNodeLikeRequest,
	createServerResponseAdapter,
} from "#/mcp/http-adapter";
import {
	executeTool,
	listToolsForMcp,
	type ToolName,
	tools,
} from "#/tools/registry";

type SessionEntry = {
	server: Server;
	transport: SSEServerTransport;
};

const sessions = new Map<string, SessionEntry>();

function createMcpServer() {
	const server = new Server(
		{ name: "buena-remote-app", version: "1.0.0" },
		{ capabilities: { tools: {} } },
	);

	server.setRequestHandler(ListToolsRequestSchema, async () => ({
		tools: listToolsForMcp(tools),
	}));

	server.setRequestHandler(CallToolRequestSchema, async (request) => {
		const result = await executeTool(
			tools,
			request.params.name as ToolName,
			request.params.arguments ?? {},
		);

		return {
			content: [
				{
					type: "text",
					text: JSON.stringify(result),
				},
			],
		};
	});

	return server;
}

export async function handleMcpSseRequest() {
	const responseAdapter = createServerResponseAdapter();
	const transport = new SSEServerTransport(
		"/api/mcp/messages",
		responseAdapter.nodeResponse as never,
	);
	const server = createMcpServer();

	transport.onclose = () => {
		sessions.delete(transport.sessionId);
	};

	sessions.set(transport.sessionId, {
		server,
		transport,
	});

	try {
		await server.connect(transport);
		return responseAdapter.toResponse();
	} catch (error) {
		sessions.delete(transport.sessionId);
		throw error;
	}
}

export async function handleMcpMessageRequest(request: Request) {
	const url = new URL(request.url);
	const sessionId = url.searchParams.get("sessionId");

	if (!sessionId) {
		return Response.json({ error: "Missing sessionId" }, { status: 400 });
	}

	const session = sessions.get(sessionId);

	if (!session) {
		return Response.json(
			{ error: `No active MCP transport for sessionId ${sessionId}` },
			{ status: 404 },
		);
	}

	const responseAdapter = createServerResponseAdapter();
	const contentType = request.headers.get("content-type") ?? "";
	const parsedBody = contentType.includes("application/json")
		? await request.json()
		: undefined;

	await session.transport.handlePostMessage(
		createNodeLikeRequest(request) as never,
		responseAdapter.nodeResponse as never,
		parsedBody,
	);

	return responseAdapter.toResponse();
}

