import { todos } from "#/db/schema";

const getTodos = createServerFn({
	method: "GET",
}).handler(async () => {
	return await db.query.todos.findMany({
		orderBy: [desc(todos.createdAt)],
	});
});

const createTodo = createServerFn({
	method: "POST",
})
	.inputValidator((data: { title: string }) => data)
