import { and, desc, eq, like } from "drizzle-orm";
import { z } from "zod";

import { db } from "#/db/index";
import * as schema from "#/db/schema";

type AppDatabase = typeof db;

const listPropertiesSchema = z.object({
	search: z.string().trim().min(1).optional(),
	limit: z.coerce.number().int().positive().max(100).default(25),
});

const getPropertyHierarchySchema = z.object({
	propertyId: z.string().trim().min(1),
});

const listFactsSchema = z.object({
	propertyId: z.string().trim().min(1).optional(),
	category: z.string().trim().min(1).optional(),
	key: z.string().trim().min(1).optional(),
	sourceId: z.string().trim().min(1).optional(),
	limit: z.coerce.number().int().positive().max(100).default(50),
});

const listCasesSchema = z.object({
	propertyId: z.string().trim().min(1).optional(),
	houseId: z.string().trim().min(1).optional(),
	apartmentId: z.string().trim().min(1).optional(),
	status: z.string().trim().min(1).optional(),
	ownerUserId: z.string().trim().min(1).optional(),
	limit: z.coerce.number().int().positive().max(100).default(50),
});

type ToolDefinition<TSchema extends z.ZodTypeAny> = {
	description: string;
	schema: TSchema;
	execute: (args: z.infer<TSchema>) => Promise<unknown>;
};

type ToolRegistryShape = Record<string, ToolDefinition<z.ZodTypeAny>>;

type InferToolArgs<TTool> =
	TTool extends ToolDefinition<infer TSchema> ? z.infer<TSchema> : never;

type InferToolResult<TTool> = TTool extends {
	execute: (args: never) => Promise<infer TResult>;
}
	? TResult
	: never;

function defineTool<TSchema extends z.ZodTypeAny>(
	definition: ToolDefinition<TSchema>,
) {
	return definition;
}

export function createToolRegistry(database: AppDatabase = db) {
	return {
		list_properties: defineTool({
			description: "Lists properties available in the hierarchy database.",
			schema: listPropertiesSchema,
			execute: async ({ limit, search }) => {
				const searchFilter = search
					? like(schema.properties.name, `%${search}%`)
					: undefined;

				return database.query.properties.findMany({
					where: searchFilter,
					limit,
					orderBy: [schema.properties.name],
				});
			},
		}),
		list_property_hierarchies: defineTool({
			description:
				"Lists properties together with their houses and apartments.",
			schema: listPropertiesSchema,
			execute: async ({ limit, search }) => {
				const searchFilter = search
					? like(schema.properties.name, `%${search}%`)
					: undefined;

				return database.query.properties.findMany({
					where: searchFilter,
					limit,
					orderBy: [schema.properties.name],
					with: {
						houses: {
							with: {
								apartments: true,
							},
						},
					},
				});
			},
		}),
		get_property_hierarchy: defineTool({
			description:
				"Fetches one property with its houses and apartments in hierarchical form.",
			schema: getPropertyHierarchySchema,
			execute: async ({ propertyId }) => {
				const property = await database.query.properties.findFirst({
					where: eq(schema.properties.id, propertyId),
					with: {
						houses: {
							with: {
								apartments: true,
							},
						},
					},
				});

				if (!property) {
					throw new Error(`Property not found: ${propertyId}`);
				}

				return property;
			},
		}),
		list_facts: defineTool({
			description:
				"Lists facts with optional filtering by property, category, key, or source.",
			schema: listFactsSchema,
			execute: async ({ category, key, limit, propertyId, sourceId }) => {
				const filters = [
					propertyId ? eq(schema.facts.propertyId, propertyId) : undefined,
					category ? eq(schema.facts.category, category) : undefined,
					key ? eq(schema.facts.key, key) : undefined,
					sourceId ? eq(schema.facts.sourceId, sourceId) : undefined,
				].filter(Boolean);

				return database.query.facts.findMany({
					where: filters.length > 0 ? and(...filters) : undefined,
					limit,
					orderBy: [desc(schema.facts.id)],
					with: {
						property: true,
						source: true,
					},
				});
			},
		}),
		list_cases: defineTool({
			description:
				"Lists cases with optional filtering by scope, status, or owner.",
			schema: listCasesSchema,
			execute: async ({
				apartmentId,
				houseId,
				limit,
				ownerUserId,
				propertyId,
				status,
			}) => {
				const filters = [
					propertyId ? eq(schema.cases.propertyId, propertyId) : undefined,
					houseId ? eq(schema.cases.houseId, houseId) : undefined,
					apartmentId ? eq(schema.cases.apartmentId, apartmentId) : undefined,
					status ? eq(schema.cases.status, status) : undefined,
					ownerUserId ? eq(schema.cases.ownerUserId, ownerUserId) : undefined,
				].filter(Boolean);

				return database.query.cases.findMany({
					where: filters.length > 0 ? and(...filters) : undefined,
					limit,
					orderBy: [desc(schema.cases.updatedAt)],
					with: {
						apartment: true,
						house: true,
						owner: true,
						property: true,
					},
				});
			},
		}),
	};
}

export function createMcpToolRegistry(database: AppDatabase = db) {
	const tools = createToolRegistry(database);

	return {
		list_property_hierarchies: tools.list_property_hierarchies,
		list_facts: tools.list_facts,
		list_cases: tools.list_cases,
	};
}

export const appTools = createToolRegistry();
export const mcpTools = createMcpToolRegistry();

export type ToolRegistry = ReturnType<typeof createToolRegistry>;
export type McpToolRegistry = ReturnType<typeof createMcpToolRegistry>;
export type ToolName = keyof ToolRegistry;

export function listToolsForMcp<TRegistry extends ToolRegistryShape>(
	toolRegistry: TRegistry,
) {
	return Object.entries(toolRegistry).map(([name, tool]) => ({
		name,
		description: tool.description,
		inputSchema: z.toJSONSchema(tool.schema),
	}));
}

export async function executeTool<
	TRegistry extends ToolRegistryShape,
	TName extends keyof TRegistry,
>(
	toolRegistry: TRegistry,
	name: TName,
	args: unknown,
): Promise<InferToolResult<TRegistry[TName]>> {
	const tool = toolRegistry[name];

	if (!tool) {
		throw new Error(`Tool not found: ${String(name)}`);
	}

	const parsedArgs = tool.schema.parse(args ?? {}) as InferToolArgs<
		TRegistry[TName]
	>;

	return tool.execute(parsedArgs) as Promise<InferToolResult<TRegistry[TName]>>;
}

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { WebStandardStreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js";
import {
	CallToolRequestSchema,
	ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";

import { executeTool, listToolsForMcp, mcpTools } from "#/tools/registry";

function createMcpServer<
	TRegistry extends Record<string, { description: string }>,
>(toolRegistry: TRegistry) {
	const server = new Server(
		{ name: "buena-remote-app", version: "1.0.0" },
		{ capabilities: { tools: {} } },
	);

	server.setRequestHandler(ListToolsRequestSchema, async () => ({
		tools: listToolsForMcp(toolRegistry),
	}));

	server.setRequestHandler(CallToolRequestSchema, async (request) => {
		const result = await executeTool(
			toolRegistry,
			request.params.name as keyof TRegistry,
			request.params.arguments ?? {},
		);

		return {
			content: [
				{
					type: "text",
					text: JSON.stringify(result),
				},
			],
		};
	});

	return server;
}

export async function handleMcpHttpRequest(
	request: Request,
	toolRegistry = mcpTools,
) {
	if (request.method !== "POST") {
		return Response.json(
			{
				jsonrpc: "2.0",
				error: {
					code: -32000,
					message: "Method not allowed.",
				},
				id: null,
			},
			{ status: 405 },
		);
	}

	const transport = new WebStandardStreamableHTTPServerTransport({
		sessionIdGenerator: undefined,
	});
	const server = createMcpServer(toolRegistry);

	await server.connect(transport);
	return await transport.handleRequest(request);
}

