import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { WebStandardStreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js";
import {
	CallToolRequestSchema,
	ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";

import { executeTool, listToolsForMcp, mcpTools } from "#/tools/registry";

function createMcpServer<
	TRegistry extends Record<string, { description: string }>,
>(toolRegistry: TRegistry) {
	const server = new Server(
		{ name: "buena-remote-app", version: "1.0.0" },
		{ capabilities: { tools: {} } },
	);

	server.setRequestHandler(ListToolsRequestSchema, async () => ({
		tools: listToolsForMcp(toolRegistry),
	}));

	server.setRequestHandler(CallToolRequestSchema, async (request) => {
		const result = await executeTool(
			toolRegistry,
			request.params.name as keyof TRegistry,
			request.params.arguments ?? {},
		);

		return {
			content: [
				{
					type: "text",
					text: JSON.stringify(result),
				},
			],
		};
	});

	return server;
}

export async function handleMcpHttpRequest(
	request: Request,
	toolRegistry = mcpTools,
) {
	if (request.method !== "POST") {
		return Response.json(
			{
				jsonrpc: "2.0",
				error: {
					code: -32000,
					message: "Method not allowed.",
				},
				id: null,
			},
			{ status: 405 },
		);
	}

	const transport = new WebStandardStreamableHTTPServerTransport({
		sessionIdGenerator: undefined,
	});
	const server = createMcpServer(toolRegistry);

	await server.connect(transport);
	return await transport.handleRequest(request);
}

